{
  "status": "answered",
  "claims": [
    {
      "text": "Феодосий III был византийским императором, правившим в 715–717 годах, и умер после 754 года.",
      "evidence_ids": [12]
    },
    {
      "text": "Дата и место рождения Феодосия III неизвестны; по одной из версий, он был сыном императора Тиберия III.",
      "evidence_ids": [13]
    },
    {
      "text": "Причины восшествия на трон: войска, недовольные управлением Анастасия II, провозгласили Феодосия императором, когда он был сборщиком податей в Мёзии.",
      "evidence_ids": [13]
    },
    {
      "text": "Феодосий сначала отказывался от престола и пытался бежать, но был принуждён к принятию власти.",
      "evidence_ids": [13]
    }
  ]
}

